var s=`0717-fufu-de-manioc`;var i=`world-0717`;var t=`CD`;var o=`central-africa`;var n=8;var r=39;var u={en:`Fufu de Manioc`,ua:`Фуфу з маніоку`};var c={en:`Fufu de Manioc is a Democratic Republic of the Congo classic prepared with cassava flour, peanut sauce. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Uses commercially processed cassava flour, not untreated raw cassava; never replace it with improperly processed cassava.`,ua:`Фуфу з маніоку, страва кухні країни Демократична Республіка Конго зі складниками: борошно маніоку, арахісовий соус. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Використовується промислово оброблене маніокове борошно, а не сирий маніок; не замінюйте його неправильно підготовленою сировиною.`};var l=[{en:`Bring water to a vigorous simmer before introducing commercially processed cassava flour; do not boil raw untreated cassava flour as a shortcut.`,ua:`Доведіть воду до активного кипіння перед додаванням промислово підготовленого маніокового борошна; не використовуйте необроблену сировину.`,t:[`boiling`],m:9,i:[[`water`,1050,`ml`]]},{en:`Gradually beat the processed cassava flour into boiling water and stir vigorously until a thick glossy paste forms.`,ua:`Поступово всипайте підготовлене маніокове борошно в окріп і енергійно вимішуйте до густої блискучої маси.`,t:[`mixing`],m:15,i:[[`cassava-flour`,350,`g`],[`water`,240,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 12 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 12 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut-sauce`,170,`g`]]}];var d={slug:s,id:i,country:`CD`,region:o,servings:8,minutes:39,title:u,text:c,steps:l};export{t as country,d as default,i as id,r as minutes,o as region,n as servings,s as slug,l as steps,c as text,u as title};